import {
  groupPlayerProps,
  type PlayerPropRow,
} from "../../lib/playerPropsGrouping";
import finishedGames from "../fixtures/nflPolymarketGrade12581.json";

// Synthetic finished-game payloads generated by the real backend assembly.
// test_source_mark_12581.py pins this file to its actual served rows.
describe("a finished NFL prop keeps one player and rung", () => {
  it.each(finishedGames)(
    "Polymarket Over won=$over_won, lone Under=$under_only, Kalshi won=$kalshi_won",
    ({ player_props, over_won, kalshi_won }) => {
      const { players, dropped } = groupPlayerProps({
        playerProps: player_props as PlayerPropRow[],
        other: [],
        homeTeam: "Houston Texans",
        awayTeam: "Buffalo Bills",
        boxScorePlayers: null,
      });
      expect(dropped).toEqual([]);
      expect(players.map((player) => player.name)).toEqual(["Josh Allen"]);
      expect(player_props).toHaveLength(1);
      expect(players[0].stats).toHaveLength(1);
      const selectedWon = kalshi_won ?? over_won;
      expect(players[0].stats[0].grade).toMatchObject({
        state: selectedWon ? "HIT" : "MISS",
        hit: selectedWon,
      });
      expect(player_props[0].outcome_name).toBe("Josh Allen: 225+");
    },
  );
});
